"""The Xray config may contain comments (Xray accepts them); the panel must read it."""
import pytest

from app.utils import jsonc

CONFIG = """
# generated by hand
{
  // inbound for phones
  "inbounds": [
    {
      "tag": "VLESS TCP REALITY", /* the main one */
      "port": 443,
      "settings": {"fallbacks": [{"dest": "https://example.com//path"}]},
      "note": "not a // comment, nor /* this */, nor # this",
      "escaped": "quote \\" // still inside the string",
    },
  ],
    # indented hash comment
  "log": {"loglevel": "warning"}
}
"""


def test_reads_comments_and_trailing_commas():
    config = jsonc.loads(CONFIG)
    inbound = config["inbounds"][0]
    assert inbound["tag"] == "VLESS TCP REALITY"
    assert inbound["port"] == 443
    assert inbound["settings"]["fallbacks"][0]["dest"] == "https://example.com//path"
    assert inbound["note"] == "not a // comment, nor /* this */, nor # this"
    assert inbound["escaped"] == 'quote " // still inside the string'
    assert config["log"] == {"loglevel": "warning"}


def test_plain_json_is_unchanged():
    assert jsonc.loads('{"a": [1, 2.5, true, null, "x"]}') == {"a": [1, 2.5, True, None, "x"]}


@pytest.mark.parametrize("bad", ['{"a": }', "/var/lib/marzban/xray_config.json", "{"])
def test_invalid_input_raises_value_error(bad):
    # XRayConfig relies on ValueError to fall back to treating the string as a path
    with pytest.raises(ValueError):
        jsonc.loads(bad)


def test_xray_config_loads_a_commented_file(tmp_path):
    from pathlib import Path

    from app.xray.config import XRayConfig

    plain = (Path(__file__).parent / "fixtures" / "xray_config.json").read_text()
    commented = "# my server\n// edited by hand\n" + plain.replace("{", "{ /* note */", 1)
    path = tmp_path / "xray.json"
    path.write_text(commented)
    assert XRayConfig(str(path), api_port=10085).inbounds_by_tag == XRayConfig(plain, api_port=10085).inbounds_by_tag
